                    >
                        <div className={style.GallerySlider__slideInner}>
                            <img
                            src={item.src}
                            className={style.GallerySlider__img}
                            />
                        </div>
                    </SwiperSlide>
                ))}
            </Swiper>
            <PhotoSwipeWrapper isOpen={isOpen} index={index} items={props.items} onClose={handleClose} />
        </div>
    )
}

